1	// Provider interface: the only way the agent reaches company data. Real and
2	// fixture providers both implement it. Plain TypeScript only.
3	
4	import type { RawCompany, RunConfig } from "../types";
5	
6	// Why a provider call failed.
7	export type ProviderErrorCategory =
8	  | "auth_failed"
9	  | "rate_limited"
10	  | "timeout"
11	  | "bad_request"
12	  | "no_match"
13	  | "budget_cap_reached"
14	  | "empty_or_partial";
15	
16	export interface ProviderError {
17	  readonly category: ProviderErrorCategory;
18	  readonly message: string;
19	}
20	
21	// Outcome of one provider call. Providers return errors; they do not throw.
22	export type ProviderResult<T> =
23	  | {
24	      readonly ok: true;
25	      readonly data: T;
26	      // US dollars this call cost.
27	      readonly cost_usd: number;
28	      // Number of upstream API calls made.
29	      readonly calls: number;
30	    }
31	  | { readonly ok: false; readonly error: ProviderError };
32	
33	// Filters for a company search.
34	export interface SearchFilters {
35	  readonly country: string;
36	  readonly industries: readonly string[];
37	  readonly employee_count_ranges: readonly string[];
38	}
39	
40	export interface CompanyProvider {
41	  autocompleteIndustry(query: string): Promise<ProviderResult<readonly string[]>>;
42	  searchCompanies(
43	    filters: SearchFilters,
44	    limit: number,
45	  ): Promise<ProviderResult<readonly RawCompany[]>>;
46	  enrichCompanies(
47	    linkedin_urls: readonly string[],
48	  ): Promise<ProviderResult<readonly RawCompany[]>>;
49	}
50	
51	// What a BudgetGuard has used so far.
52	export interface BudgetSnapshot {
53	  readonly cost_usd: number;
54	  readonly searched: number;
55	  readonly enriched: number;
56	}
57	
58	// Tracks spend against the run's caps. Providers must check it before every
59	// paid call and return budget_cap_reached instead of calling when it says no.
60	export class BudgetGuard {
61	  private readonly max_search_results: number;
62	  private readonly max_enrichments: number;
63	  private cost_usd = 0;
64	  private searched = 0;
65	  private enriched = 0;
66	
67	  constructor(config: Pick<RunConfig, "max_search_results" | "max_enrichments">) {
68	    this.max_search_results = config.max_search_results;
69	    this.max_enrichments = config.max_enrichments;
70	  }
71	
72	  // True if searching `limit` more companies stays within the cap.
73	  canSearch(limit: number): boolean {
74	    return limit >= 0 && this.searched + limit <= this.max_search_results;
75	  }
76	
77	  // True if enriching `count` more companies stays within the cap.
78	  canEnrich(count: number): boolean {
79	    return count >= 0 && this.enriched + count <= this.max_enrichments;
80	  }
81	
82	  recordSearch(n: number, cost: number): void {
83	    this.searched += n;
84	    this.cost_usd += cost;
85	  }
86	
87	  recordEnrich(n: number, cost: number): void {
88	    this.enriched += n;
89	    this.cost_usd += cost;
90	  }
91	
92	  snapshot(): BudgetSnapshot {
93	    return {
94	      cost_usd: this.cost_usd,
95	      searched: this.searched,
96	      enriched: this.enriched,
97	    };
98	  }
99	}
