1	// Deterministic CompanyProvider backed by the synthetic fixtures. No network.
2	
3	import { FIXTURE_COMPANIES } from "../fixtures/companies";
4	import type { RawCompany, RunConfig } from "../types";
5	import { normalizeLinkedInUrl } from "./normalize";
6	import {
7	  BudgetGuard,
8	  type CompanyProvider,
9	  type ProviderErrorCategory,
10	  type ProviderResult,
11	  type SearchFilters,
12	} from "./provider";
13	
14	// Make the Nth call (1-based, counted across all three methods) fail.
15	export interface InjectedFailure {
16	  readonly call_number: number;
17	  readonly category: ProviderErrorCategory;
18	  readonly message?: string;
19	}
20	
21	export interface FixtureProviderOptions {
22	  readonly config: Pick<RunConfig, "max_search_results" | "max_enrichments">;
23	  // Cost of each call: a fixed amount, or a function of the 1-based call
24	  // number. Default 0.
25	  readonly cost_usd?: number | ((call_number: number) => number);
26	  // Price per record, used only when cost_usd is not given: a successful call
27	  // costs the price times the records returned (search) or matched (enrich).
28	  readonly cost_per_record?: { readonly search?: number; readonly enrich?: number };
29	  readonly failures?: readonly InjectedFailure[];
30	  // Defaults to the synthetic fixtures.
31	  readonly companies?: readonly RawCompany[];
32	}
33	
34	export class FixtureProvider implements CompanyProvider {
35	  readonly budget: BudgetGuard;
36	  private readonly cost_usd: number | ((call_number: number) => number);
37	  private readonly cost_per_record: { readonly search: number; readonly enrich: number };
38	  private readonly per_record_pricing: boolean;
39	  private readonly failures: readonly InjectedFailure[];
40	  private readonly companies: readonly RawCompany[];
41	  private call_count = 0;
42	
43	  constructor(options: FixtureProviderOptions) {
44	    this.budget = new BudgetGuard(options.config);
45	    this.cost_usd = options.cost_usd ?? 0;
46	    this.per_record_pricing =
47	      options.cost_usd === undefined && options.cost_per_record !== undefined;
48	    this.cost_per_record = {
49	      search: options.cost_per_record?.search ?? 0,
50	      enrich: options.cost_per_record?.enrich ?? 0,
51	    };
52	    this.failures = options.failures ?? [];
53	    this.companies = options.companies ?? FIXTURE_COMPANIES;
54	  }
55	
56	  // Number of calls made so far, including failed ones.
57	  get calls_made(): number {
58	    return this.call_count;
59	  }
60	
61	  private nextCall(): { n: number; cost: number; failure?: InjectedFailure } {
62	    this.call_count += 1;
63	    const n = this.call_count;
64	    const cost = typeof this.cost_usd === "function" ? this.cost_usd(n) : this.cost_usd;
65	    return { n, cost, failure: this.failures.find((f) => f.call_number === n) };
66	  }
67	
68	  async autocompleteIndustry(query: string): Promise<ProviderResult<readonly string[]>> {
69	    const { failure } = this.nextCall();
70	    if (failure) return fail(failure.category, failure.message);
71	    const q = query.trim().toLowerCase();
72	    const matches = [
73	      ...new Set(this.companies.map((c) => c.industry).filter((i) => i !== "")),
74	    ].filter((i) => i.toLowerCase().includes(q));
75	    if (q === "" || matches.length === 0) {
76	      return fail("no_match", `no industry matches "${query}"`);
77	    }
78	    // Autocomplete is free and outside the search/enrich caps.
79	    return { ok: true, data: matches, cost_usd: 0, calls: 1 };
80	  }
81	
82	  async searchCompanies(
83	    filters: SearchFilters,
84	    limit: number,
85	  ): Promise<ProviderResult<readonly RawCompany[]>> {
86	    if (!this.budget.canSearch(limit)) {
87	      return fail("budget_cap_reached", "search cap would be exceeded");
88	    }
89	    const { cost, failure } = this.nextCall();
90	    if (failure) return fail(failure.category, failure.message);
91	    const industries = filters.industries.map((i) => i.toLowerCase());
92	    const found = this.companies
93	      .filter((c) => {
94	        if (industries.length > 0 && !industries.includes(c.industry.toLowerCase())) {
95	          return false;
96	        }
97	        if (
98	          filters.employee_count_ranges.length > 0 &&
99	          !filters.employee_count_ranges.includes(c.employee_count_range)
100	        ) {
101	          return false;
102	        }
103	        // Records with no location pass: the fixtures rarely carry one.
104	        const country = c.location?.country;
105	        return !country || !filters.country || country.toLowerCase() === filters.country.toLowerCase();
106	      })
107	      .slice(0, limit)
108	      .map((c): RawCompany => ({ ...c, source: "search" }));
109	    if (found.length === 0) return fail("no_match", "no companies match the filters");
110	    const total = this.per_record_pricing ? this.cost_per_record.search * found.length : cost;
111	    this.budget.recordSearch(found.length, total);
112	    return { ok: true, data: found, cost_usd: total, calls: 1 };
113	  }
114	
115	  async enrichCompanies(
116	    linkedin_urls: readonly string[],
117	  ): Promise<ProviderResult<readonly RawCompany[]>> {
118	    if (!this.budget.canEnrich(linkedin_urls.length)) {
119	      return fail("budget_cap_reached", "enrichment cap would be exceeded");
120	    }
121	    const { cost, failure } = this.nextCall();
122	    if (failure) return fail(failure.category, failure.message);
123	    const wanted = new Set(linkedin_urls.map(normalizeLinkedInUrl));
124	    const found = this.companies.filter(
125	      (c) => c.professional_network_url !== "" && wanted.has(normalizeLinkedInUrl(c.professional_network_url)),
126	    );
127	    // Unmatched URLs are simply absent from data; if none match, no_match.
128	    if (found.length === 0) return fail("no_match", "no fixture matches the LinkedIn URLs");
129	    const total = this.per_record_pricing ? this.cost_per_record.enrich * found.length : cost;
130	    this.budget.recordEnrich(found.length, total);
131	    return { ok: true, data: found, cost_usd: total, calls: 1 };
132	  }
133	}
134	
135	function fail(category: ProviderErrorCategory, message?: string): ProviderResult<never> {
136	  return { ok: false, error: { category, message: message ?? category } };
137	}
138

1	import { describe, expect, it } from "vitest";
2	import { FixtureProvider } from "../src/core/data/fixture-provider";
3	import { BudgetGuard } from "../src/core/data/provider";
4	import { FIXTURE_COMPANIES } from "../src/core/fixtures/companies";
5	
6	const open = { country: "", industries: [], employee_count_ranges: [] };
7	
8	function make(max_search_results = 100, max_enrichments = 15, extra = {}) {
9	  return new FixtureProvider({ config: { max_search_results, max_enrichments }, ...extra });
10	}
11	
12	describe("BudgetGuard", () => {
13	  it("refuses calls that would exceed a cap", () => {
14	    const g = new BudgetGuard({ max_search_results: 5, max_enrichments: 2 });
15	    expect(g.canSearch(5)).toBe(true);
16	    expect(g.canSearch(6)).toBe(false);
17	    g.recordSearch(3, 0.1);
18	    expect(g.canSearch(3)).toBe(false);
19	    g.recordEnrich(2, 0.2);
20	    expect(g.canEnrich(1)).toBe(false);
21	    expect(g.snapshot()).toEqual({ cost_usd: expect.closeTo(0.3), searched: 3, enriched: 2 });
22	  });
23	});
24	
25	describe("FixtureProvider caps", () => {
26	  it("returns budget_cap_reached without making the call", async () => {
27	    const p = make(3, 1);
28	    const first = await p.searchCompanies(open, 3);
29	    expect(first.ok && first.data.length).toBe(3);
30	    const second = await p.searchCompanies(open, 1);
31	    expect(!second.ok && second.error.category).toBe("budget_cap_reached");
32	    const urls = FIXTURE_COMPANIES.slice(0, 2).map((c) => c.professional_network_url);
33	    const enrich = await p.enrichCompanies(urls);
34	    expect(!enrich.ok && enrich.error.category).toBe("budget_cap_reached");
35	    expect(p.calls_made).toBe(1);
36	  });
37	
38	  it("tracks simulated cost", async () => {
39	    const p = make(100, 15, { cost_usd: 0.5 });
40	    const r = await p.searchCompanies(open, 2);
41	    expect(r.ok && r.cost_usd).toBe(0.5);
42	    expect(p.budget.snapshot()).toEqual({ cost_usd: 0.5, searched: 2, enriched: 0 });
43	  });
44	
45	  it("costs nothing by default", async () => {
46	    const r = await make().searchCompanies(open, 2);
47	    expect(r.ok && r.cost_usd).toBe(0);
48	  });
49	});
50	
51	describe("FixtureProvider cost_per_record", () => {
52	  const prices = { search: 0.1, enrich: 0.5 };
53	
